        return decoderRuntimeApplyLinear(self, .{
            .slot = request.linear_slot,
            .input = normed,
            .in_dim = request.hidden_size,
            .out_dim = request.out_dim,
        });
    }

    const output = try std.heap.c_allocator.alloc(f32, request.out_dim);
