    if (request.first_k != 1 or request.second_k == 0) return null;
    if (request.first_rhs_contract_axis > 1 or request.second_rhs_contract_axis > 1 or request.output_rhs_contract_axis > 1) return null;
    if (!request.first_lhs.isDevice() or !request.first_rhs.isDevice() or
        !request.second_lhs.isDevice() or !request.second_rhs.isDevice() or
        !request.gelu_input.isDevice() or !request.output_rhs.isDevice()) return null;
    if (request.first_lhs.elemCount() != request.rows or request.first_rhs.elemCount() != request.intermediate_size) return null;
    if (request.second_lhs.elemCount() != request.rows * request.second_k or request.second_rhs.elemCount() != request.intermediate_size * request.second_k) return null;
    if (request.gelu_input.elemCount() != request.rows * request.intermediate_size) return null;
    if (request.output_rhs.elemCount() != request.hidden_size * request.intermediate_size) return null;

    const intermediate_shape = [_]i32{ @intCast(request.rows), @intCast(request.intermediate_size) };
    const output_shape = [_]i32{ @intCast(request.rows), @intCast(request.hidden_size) };
    var first = try MetalTensor.deviceAllocate(runtime, request.rows * request.intermediate_size * @sizeOf(f32), .private, &intermediate_shape);
    errdefer first.deinit();
    var gelu = try MetalTensor.deviceAllocate(runtime, request.rows * request.intermediate_size * @sizeOf(f32), .private, &intermediate_shape);
    errdefer gelu.deinit();
    var output = try MetalTensor.deviceAllocate(runtime, request.rows * request.hidden_size * @sizeOf(f32), .private, &output_shape);
    errdefer output.deinit();

    stats.decoder_runtime_apply_activation_calls += 1;
    const rc = termite_metal_decode_runtime_ffn_gelu_backward_output_f32_device(
        runtime,
        request.first_lhs.deviceHandle(),
        request.first_lhs.deviceByteOffset(),
        request.first_rhs.deviceHandle(),
        request.first_rhs.deviceByteOffset(),
        request.second_lhs.deviceHandle(),
        request.second_lhs.deviceByteOffset(),
        request.second_rhs.deviceHandle(),
        request.second_rhs.deviceByteOffset(),
        request.second_rhs_contract_axis,
        request.gelu_input.deviceHandle(),
        request.gelu_input.deviceByteOffset(),
        request.output_rhs.deviceHandle(),
        request.output_rhs.deviceByteOffset(),
        request.output_rhs_contract_axis,
        request.rows,
        request.hidden_size,
        request.intermediate_size,
        request.second_k,
        if (request.exact) 1 else 0,
        first.deviceHandle(),
        first.deviceByteOffset(),
        gelu.deviceHandle(),
        gelu.deviceByteOffset(),
        output.deviceHandle(),
        output.deviceByteOffset(),
    );
    if (rc != 0) {
        first.deinit();
        gelu.deinit();
        output.deinit();
        return null;
    }
    return .{ .first = first, .gelu = gelu, .output = output };
}

pub fn decoderRuntimeApplyPrimitiveUnary(self: anytype, input: MetalTensor, activation_kind: u32) !?MetalTensor {
    return decoderRuntimeApplyPrimitiveUnaryImpl(self, input, activation_kind, null);
}

pub fn decoderRuntimeApplyPrimitiveUnaryInto(self: anytype, input: MetalTensor, activation_kind: u32, output_override: MetalTensor) !?MetalTensor {
    return decoderRuntimeApplyPrimitiveUnaryImpl(self, input, activation_kind, output_override);
}

fn decoderRuntimeApplyPrimitiveUnaryImpl(self: anytype, input: MetalTensor, activation_kind: u32, output_override: ?MetalTensor) !?MetalTensor {
    const runtime = self.raw_decode_runtime orelse return null;
    if (termite_metal_decode_runtime_ready(runtime) == 0) return null;
    if (!input.isDevice()) return null;
    const dim = input.elemCount();
    if (dim == 0) return null;
    if (output_override) |override| {
        if (!override.isDevice() or override.elemCount() != dim) return null;
        const rc = termite_metal_decode_runtime_apply_activation_device(
            runtime,
            activation_kind,
            input.deviceHandle(),
            input.deviceByteOffset(),
            1,
            dim,
            override.deviceHandle(),
            override.deviceByteOffset(),
        );
        if (rc != 0) return null;
        return override;
    }
    var output_device = try MetalTensor.deviceAllocate(runtime, dim * @sizeOf(f32), .private, input.shape());
    errdefer output_device.deinit();
    const rc = termite_metal_decode_runtime_apply_activation_device(
        runtime,
        activation_kind,
        input.deviceHandle(),
        input.deviceByteOffset(),
        1,
        dim,
        output_device.deviceHandle(),
        output_device.deviceByteOffset(),
    );
    return finishDeviceOutput(&output_device, rc);
}

pub fn decoderRuntimeApplySoftmaxDevice(self: anytype, input: MetalTensor, rows: usize, dim: usize, log_softmax: bool) !?MetalTensor {
    const runtime = self.raw_decode_runtime orelse return null;
    if (termite_metal_decode_runtime_ready(runtime) == 0) return null;
    if (!input.isDevice()) return null;
    if (rows == 0 or dim == 0) return null;
    if (rows > std.math.maxInt(usize) / dim) return null;
    if (input.elemCount() != rows * dim) return null;
    var output_device = try MetalTensor.deviceAllocate(runtime, rows * dim * @sizeOf(f32), .private, input.shape());
    errdefer output_device.deinit();
    const rc = termite_metal_decode_runtime_apply_softmax_device(
        runtime,
        input.deviceHandle(),
        input.deviceByteOffset(),
        rows,
        dim,
        @intFromBool(log_softmax),
        output_device.deviceHandle(),
        output_device.deviceByteOffset(),
    );
    return finishDeviceOutput(&output_device, rc);
}

pub fn decoderRuntimeSelectMoeRoutesDevice(
    self: anytype,
    layer_index: usize,
    logits: MetalTensor,
    rows: usize,
    num_experts: usize,
    top_k: usize,
    logit_scale: f32,
    route_ids: []u32,
    route_weights: []f32,
) !bool {
    const runtime = self.raw_decode_runtime orelse return false;
    if (termite_metal_decode_runtime_ready(runtime) == 0 or !logits.isDevice()) return false;
    if (layer_index >= 32 or rows == 0 or num_experts == 0 or num_experts > 128 or top_k == 0 or top_k > 8 or top_k > num_experts) return false;
    const logits_count = std.math.mul(usize, rows, num_experts) catch return false;
    const route_count = std.math.mul(usize, rows, top_k) catch return false;
    if (logits.elemCount() != logits_count or route_ids.len != route_count or route_weights.len != route_count) return false;
    return termite_metal_decode_runtime_select_moe_routes_device(
        runtime,
        layer_index,
        logits.deviceHandle(),
        logits.deviceByteOffset(),
        rows,
        num_experts,
        top_k,
        logit_scale,
        route_ids.ptr,
        route_weights.ptr,
    ) == 0;
}

pub fn decoderRuntimeSelectMoeRoutesOptimisticDevice(
    self: anytype,
    layer_index: usize,
    logits: MetalTensor,
    rows: usize,
    num_experts: usize,
    top_k: usize,
    logit_scale: f32,
) bool {
    const runtime = self.raw_decode_runtime orelse return false;
    if (termite_metal_decode_runtime_ready(runtime) == 0 or !logits.isDevice()) return false;
    if (layer_index >= 32 or rows != 1 or num_experts == 0 or num_experts > 128 or top_k == 0 or top_k > 8 or top_k > num_experts) return false;
    const logits_count = std.math.mul(usize, rows, num_experts) catch return false;
    if (logits.elemCount() != logits_count) return false;
    return termite_metal_decode_runtime_select_moe_routes_device(
        runtime,
        layer_index,
        logits.deviceHandle(),
        logits.deviceByteOffset(),
        rows,
        num_experts,
        top_k,
        logit_scale,
        null,
        null,
    ) == 0;
}

/// Encode route selection into the active frame and retain compact IDs and
/// weights in runtime-owned device buffers. No slot map, checkpoint ledger, or
/// host readback is involved; a following fused MoE dispatch must consume the
/// buffers before another route selection overwrites them.
pub fn decoderRuntimeSelectMoeRoutesBufferedDevice(
    self: anytype,
    layer_index: usize,
    logits: MetalTensor,
    rows: usize,
    num_experts: usize,
    top_k: usize,
    logit_scale: f32,
) bool {
    const runtime = self.raw_decode_runtime orelse return false;
    if (termite_metal_decode_runtime_ready(runtime) == 0 or !logits.isDevice()) return false;
    if (layer_index >= 32 or rows == 0 or num_experts == 0 or num_experts > 128 or top_k == 0 or top_k > 8 or top_k > num_experts) return false;
    const logits_count = std.math.mul(usize, rows, num_experts) catch return false;
    if (logits.elemCount() != logits_count) return false;
    return termite_metal_decode_runtime_select_moe_routes_buffered_device(
        runtime,
        layer_index,
        logits.deviceHandle(),
        logits.deviceByteOffset(),
        rows,
        num_experts,
        top_k,
        logit_scale,
    ) == 0;
}

pub const MoeCheckpointError = error{MoeCheckpointUnavailable};

pub fn decoderRuntimeBeginMoeCheckpoint(self: anytype, layer_count: usize) bool {
    const runtime = self.raw_decode_runtime orelse return false;
    return termite_metal_decode_runtime_begin_moe_checkpoint(runtime, layer_count) == 0;
}

pub fn decoderRuntimeFinishMoeCheckpoint(self: anytype, layer_count: usize, top_k: usize) MoeCheckpointError!u64 {
    const runtime = self.raw_decode_runtime orelse return error.MoeCheckpointUnavailable;
    var miss_mask: u64 = 0;
    if (termite_metal_decode_runtime_finish_moe_checkpoint(runtime, layer_count, top_k, &miss_mask) != 0) {
        return error.MoeCheckpointUnavailable;
    }
    return miss_mask;
}

pub fn decoderRuntimeNoteMoeCheckpointReplay(self: anytype) bool {
    const runtime = self.raw_decode_runtime orelse return false;
    return termite_metal_decode_runtime_note_moe_checkpoint_replay(runtime) == 0;
}

/// Publish a fail-closed expert-id -> arena-slot directory for one MoE layer.
/// The C runtime rejects publication while a non-empty frame is in flight, so
/// callers cannot mutate a Shared table still referenced by queued GPU work.
pub fn decoderRuntimePublishMoeExpertSlotMap(
    self: anytype,
    layer_index: usize,
    expert_to_slot: []const u32,
) bool {
    const runtime = self.raw_decode_runtime orelse return false;
    if (termite_metal_decode_runtime_ready(runtime) == 0) return false;
    if (layer_index >= 32 or expert_to_slot.len == 0 or expert_to_slot.len > 128) return false;
    return termite_metal_decode_runtime_publish_moe_expert_slot_map(
        runtime,
        layer_index,
        expert_to_slot.ptr,
        expert_to_slot.len,
    ) == 0;
}

