pub fn reserveGraphPlanSlot(runtime: ?*RawMetalDecodeRuntime, slot: usize, bytes: usize) GraphPlanError!void {
    return switch (termite_metal_decode_runtime_reserve_graph_plan_slot(runtime, slot, bytes)) {
