    termite_metal_decode_runtime_roofline_invalidate(runtime);
}

pub fn deviceConcatRow(
    self: anytype,
    a: MetalTensor,
    b: MetalTensor,
    dim_a: usize,
    dim_b: usize,
) !?MetalTensor {
    const runtime = self.raw_decode_runtime orelse return null;
    if (termite_metal_decode_runtime_ready(runtime) == 0) return null;
    if (!a.isDevice() or !b.isDevice()) return null;
    const a_bytes = dim_a * @sizeOf(f32);
    const b_bytes = dim_b * @sizeOf(f32);
    if (a.deviceByteLen() < a_bytes or b.deviceByteLen() < b_bytes) return null;
    const shape = [_]i32{ 1, @intCast(dim_a + dim_b) };
    var output = try MetalTensor.deviceAllocate(runtime, a_bytes + b_bytes, .private, &shape);
    errdefer output.deinit();
    const rc = termite_metal_decode_runtime_concat_rows_device(
        runtime,
        a.deviceHandle(),
        a.deviceByteOffset(),
        a_bytes,
        b.deviceHandle(),
        b.deviceByteOffset(),
        b_bytes,
        output.deviceHandle(),
        output.deviceByteOffset(),
    );
    if (rc != 0) {
        // return null is not an error return, so the errdefer above
        // does not run; release the fresh device buffer explicitly.
        output.deinit();
        return null;
    }
    return output;
}

