    };

    const duped = try dupQuantizedStorage(&storage);
    defer {
        duped.deinit();
        std.heap.c_allocator.destroy(duped);
    }

    try std.testing.expect(!duped.raw_owned);
    try std.testing.expect(duped.raw_mmap_backed);
