    const paged_layer = .{
        .slot = @as(usize, 0),
        .format = raw_f32_kv_format,
        .page_size_tokens = @as(u16, @intCast(page_size)),
        .key_row_bytes = key_row_bytes,
        .base_key_row_bytes = key_row_bytes,
