    try beginFrame(runtime);
    var planned_paged = (try runAttentionPagedGatedDecoderBlockQuantizedDevice(&provider, .{
        .query_sequence_len = 1,
        .kv_tokens = kv_tokens,
        .num_heads = num_heads,
