        .ple_post_norm_slot = @as(?usize, 3),
        .ple_hidden_size = ple_hidden_size,
        .planned_layer_contract = paged_planned_contract,
    }, q, k_suffix, v_suffix, residual, paged_layer, block_offsets[0..], planned_paged_output, &stats));
    try submitFrame(runtime);
    try waitFrame(runtime);

    var planned_paged_output_mut = planned_paged_output;
    const paged_into_actual = try tensorHostSlice(&planned_paged_output_mut);
    try std.testing.expectEqual(expected.len, paged_into_actual.len);
    for (expected, paged_into_actual) |exp, got| {
        try std.testing.expectApproxEqAbs(exp, got, 1e-3);
    }
}

test "metal native flash prefill direct KV is bounded, counted, and disable-wins" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const enable_env = "TERMITE_METAL_ENABLE_PREFILL_SG_DIRECT_LOAD";
    const disable_env = "TERMITE_METAL_DISABLE_PREFILL_SG_DIRECT_LOAD";
    const generated_enable_env = "TERMITE_METAL_ENABLE_FLASH_PREFILL_GENERATED";
    const generated_disable_env = "TERMITE_METAL_DISABLE_FLASH_PREFILL_GENERATED";
    const original_enable = if (std.c.getenv(enable_env)) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    const original_disable = if (std.c.getenv(disable_env)) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    const original_generated_enable = if (std.c.getenv(generated_enable_env)) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    const original_generated_disable = if (std.c.getenv(generated_disable_env)) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    defer {
        if (original_enable) |value| {
            _ = setenv(enable_env, value.ptr, 1);
            std.testing.allocator.free(value);
        } else {
            _ = unsetenv(enable_env);
        }
        if (original_disable) |value| {
            _ = setenv(disable_env, value.ptr, 1);
            std.testing.allocator.free(value);
        } else {
            _ = unsetenv(disable_env);
        }
        if (original_generated_enable) |value| {
            _ = setenv(generated_enable_env, value.ptr, 1);
            std.testing.allocator.free(value);
        } else {
            _ = unsetenv(generated_enable_env);
        }
        if (original_generated_disable) |value| {
            _ = setenv(generated_disable_env, value.ptr, 1);
            std.testing.allocator.free(value);
        } else {
            _ = unsetenv(generated_disable_env);
        }
    }
    try std.testing.expectEqual(@as(c_int, 0), setenv(enable_env, "1", 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv(disable_env));
    try std.testing.expectEqual(@as(c_int, 0), setenv(generated_enable_env, "1", 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv(generated_disable_env));

    const Exercise = struct {
        fn run(expect_direct: bool, output: []f32) !void {
            const runtime = termite_metal_decode_runtime_create() orelse return error.SkipZigTest;
            defer termite_metal_decode_runtime_destroy(runtime);
            defer _ = termite_metal_decode_runtime_reset_state(runtime);
            if (termite_metal_decode_runtime_ready(runtime) == 0) return error.SkipZigTest;

            const q_len: usize = 8;
            const kv_tokens: usize = 16;
            const num_heads: usize = 8;
            const num_kv_heads: usize = 2;
            const head_dim: usize = 256;
            const sliding_window: usize = 512;
            const kv_dim: usize = num_kv_heads * head_dim;
            const q_dim: usize = num_heads * head_dim;
            const page_size: usize = 16;
            const key_row_bytes: usize = kv_dim * @sizeOf(f16);
            try std.testing.expectEqual(q_len * q_dim, output.len);

            var q_data: [q_len * q_dim]f32 = undefined;
            var k_data: [kv_tokens * kv_dim]f32 = undefined;
            var v_data: [kv_tokens * kv_dim]f32 = undefined;
            for (&q_data, 0..) |*value, i| value.* = @as(f32, @floatFromInt(@as(i32, @intCast(i % 13)) - 6)) * 0.03125;
            for (&k_data, 0..) |*value, i| value.* = @as(f32, @floatFromInt(@as(i32, @intCast(i % 17)) - 8)) * 0.03125;
            for (&v_data, 0..) |*value, i| value.* = @as(f32, @floatFromInt(@as(i32, @intCast(i % 19)) - 9)) * 0.03125;

            var q = try testDeviceTensorFromSlice(runtime, &q_data, &[_]i32{ @intCast(q_len), @intCast(q_dim) });
            defer q.deinit();
            var k = try testDeviceTensorFromSlice(runtime, &k_data, &[_]i32{ @intCast(kv_tokens), @intCast(kv_dim) });
            defer k.deinit();
            var v = try testDeviceTensorFromSlice(runtime, &v_data, &[_]i32{ @intCast(kv_tokens), @intCast(kv_dim) });
            defer v.deinit();
            var out = try MetalTensor.deviceAllocate(runtime, q_len * q_dim * @sizeOf(f32), .private, &[_]i32{ @intCast(q_len), @intCast(q_dim) });
            defer out.deinit();

            // Logical token zero starts at physical token 16. Attention is
            // deliberately given an invalid unused tail entry: only the one
            // block needed by kv_tokens may be validated or uploaded.
            const update_blocks = [_]u32{16};
            const attention_blocks = [_]u32{ 16, std.math.maxInt(u32) };
            try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_reset_attention_span_slot(runtime, 0));
            try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_update_attention_paged_from_f32_key_device_slot(
                runtime,
                0,
                3,
                k.deviceHandle(),
                k.deviceByteOffset(),
                v.deviceHandle(),
                v.deviceByteOffset(),
                kv_tokens,
                kv_tokens,
                num_kv_heads,
                head_dim,
                key_row_bytes,
                key_row_bytes,
                kv_dim,
                0,
                &update_blocks,
                update_blocks.len,
                page_size,
            ));

            const before = runtimeMemorySnapshot(runtime);
            try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_attention_paged_slot_device(
                runtime,
                0,
                3,
                q.deviceHandle(),
                q.deviceByteOffset(),
                &attention_blocks,
                attention_blocks.len,
                page_size,
                q_len,
                kv_tokens,
                num_heads,
                num_kv_heads,
                head_dim,
                key_row_bytes,
                key_row_bytes,
                kv_tokens - q_len,
                0,
                sliding_window,
                0.0,
                null,
                0,
                out.deviceHandle(),
                out.deviceByteOffset(),
            ));
            const after_prefill = runtimeMemorySnapshot(runtime);
            try std.testing.expectEqual(before.generated_attention_flash_prefill_calls + 1, after_prefill.generated_attention_flash_prefill_calls);
            if (expect_direct) {
                try std.testing.expectEqual(before.attention_prefill_direct_kv_calls + 1, after_prefill.attention_prefill_direct_kv_calls);
                try std.testing.expectEqual(before.attention_prefill_paged_kv_calls, after_prefill.attention_prefill_paged_kv_calls);
            } else {
                try std.testing.expectEqual(before.attention_prefill_direct_kv_calls, after_prefill.attention_prefill_direct_kv_calls);
                try std.testing.expectEqual(before.attention_prefill_paged_kv_calls + 1, after_prefill.attention_prefill_paged_kv_calls);
            }
            var out_mut = out;
            const prefill_output = try tensorHostSlice(&out_mut);
            @memcpy(output, prefill_output);

            // A decode-shaped call on the same contiguous table cannot select
            // or count either prefill K/V route.
            try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_attention_paged_slot_device(
                runtime,
                0,
                3,
                q.deviceHandle(),
                q.deviceByteOffset(),
                &attention_blocks,
                attention_blocks.len,
                page_size,
                1,
                kv_tokens,
                num_heads,
                num_kv_heads,
                head_dim,
                key_row_bytes,
                key_row_bytes,
                kv_tokens - 1,
                0,
                sliding_window,
                0.0,
                null,
                0,
                out.deviceHandle(),
                out.deviceByteOffset(),
            ));
            const after_decode = runtimeMemorySnapshot(runtime);
            try std.testing.expectEqual(after_prefill.attention_prefill_direct_kv_calls, after_decode.attention_prefill_direct_kv_calls);
            try std.testing.expectEqual(after_prefill.attention_prefill_paged_kv_calls, after_decode.attention_prefill_paged_kv_calls);
        }
    };

    var direct_output: [8 * 8 * 256]f32 = undefined;
    var paged_output: [8 * 8 * 256]f32 = undefined;
    try Exercise.run(true, &direct_output);
    try std.testing.expectEqual(@as(c_int, 0), setenv(disable_env, "1", 1));
    try Exercise.run(false, &paged_output);
    try std.testing.expectEqualSlices(f32, &direct_output, &paged_output);
}

test "metal native paged attention f16 single row uses 1x kernel across pages" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    // The production GQA split route now takes precedence for this shape.
    // Isolate the legacy 1x kernel this test names, and restore caller state.
    const split_disable_env = "TERMITE_METAL_DISABLE_DECODE_GQA_SPLIT";
    const one_x_disable_env = "TERMITE_METAL_DISABLE_PAGED_ATTENTION_1X";
    const original_split_disable = if (std.c.getenv(split_disable_env)) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    const original_one_x_disable = if (std.c.getenv(one_x_disable_env)) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    defer {
        if (original_split_disable) |value| {
            _ = setenv(split_disable_env, value.ptr, 1);
            std.testing.allocator.free(value);
        } else {
            _ = unsetenv(split_disable_env);
        }
        if (original_one_x_disable) |value| {
            _ = setenv(one_x_disable_env, value.ptr, 1);
            std.testing.allocator.free(value);
        } else {
            _ = unsetenv(one_x_disable_env);
        }
    }
    try std.testing.expectEqual(@as(c_int, 0), setenv(split_disable_env, "1", 1));
    try std.testing.expectEqual(@as(c_int, 0), unsetenv(one_x_disable_env));

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;

    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;
    if (termite_metal_decode_runtime_ready(runtime) == 0) return error.SkipZigTest;

    const q_len: usize = 1;
    // Stay just below the split-GQA production threshold so this test keeps
    // exercising the legacy paged-1x route it is named for.
    const kv_tokens: usize = 511;
    const num_heads: usize = 8;
    const num_kv_heads: usize = 2;
    const head_dim: usize = 256;
    const sliding_window: usize = 512;
    const kv_dim: usize = num_kv_heads * head_dim;
    const q_dim: usize = num_heads * head_dim;

    var q_data: [q_dim]f32 = undefined;
    var k_data: [kv_tokens * kv_dim]f32 = undefined;
    var v_data: [kv_tokens * kv_dim]f32 = undefined;
    for (&q_data, 0..) |*value, i| {
        const signed = @as(i32, @intCast((i * 5) % 17)) - 8;
        value.* = @as(f32, @floatFromInt(signed)) * 0.125;
    }
    for (&k_data, 0..) |*value, i| {
        const signed = @as(i32, @intCast((i * 7 + 3) % 19)) - 9;
        value.* = @as(f32, @floatFromInt(signed)) * 0.0625;
    }
    for (&v_data, 0..) |*value, i| {
        const signed = @as(i32, @intCast((i * 11 + 5) % 23)) - 11;
        value.* = @as(f32, @floatFromInt(signed)) * 0.03125;
    }

    var q = try testDeviceTensorFromSlice(runtime, &q_data, &[_]i32{ @intCast(q_len), @intCast(q_dim) });
    defer q.deinit();
    var k = try testDeviceTensorFromSlice(runtime, &k_data, &[_]i32{ @intCast(kv_tokens), @intCast(kv_dim) });
    defer k.deinit();
    var v = try testDeviceTensorFromSlice(runtime, &v_data, &[_]i32{ @intCast(kv_tokens), @intCast(kv_dim) });
    defer v.deinit();
    var out = try MetalTensor.deviceAllocate(runtime, q_dim * @sizeOf(f32), .private, &[_]i32{ @intCast(q_len), @intCast(q_dim) });
    defer out.deinit();

    const f16_kv_format: u32 = 3;
    const page_size: usize = 16;
    const key_row_bytes: usize = kv_dim * @sizeOf(f16);
    const block_count = (kv_tokens + page_size - 1) / page_size;
    var block_offsets: [block_count]u32 = undefined;
    for (&block_offsets, 0..) |*offset, i| offset.* = @intCast(i * page_size);
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_reset_attention_span_slot(runtime, 0));
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_update_attention_paged_from_f32_key_device_slot(
        runtime,
        0,
        f16_kv_format,
        k.deviceHandle(),
        k.deviceByteOffset(),
        v.deviceHandle(),
        v.deviceByteOffset(),
        kv_tokens,
        kv_tokens,
        num_kv_heads,
        head_dim,
        key_row_bytes,
        key_row_bytes,
        kv_dim,
        0,
        &block_offsets,
        block_offsets.len,
        page_size,
    ));

    const before = runtimeMemorySnapshot(runtime);
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_attention_paged_slot_device(
        runtime,
        0,
        f16_kv_format,
        q.deviceHandle(),
        q.deviceByteOffset(),
        &block_offsets,
        block_offsets.len,
        page_size,
        q_len,
        kv_tokens,
        num_heads,
        num_kv_heads,
        head_dim,
        key_row_bytes,
        key_row_bytes,
        kv_tokens - 1,
        0,
        sliding_window,
        0.0,
        null,
        0,
        out.deviceHandle(),
        out.deviceByteOffset(),
    ));
    const after = runtimeMemorySnapshot(runtime);
    try std.testing.expect(after.paged_attention_1x_calls > before.paged_attention_1x_calls);

    var expected: [q_dim]f32 = [_]f32{0.0} ** q_dim;
    const heads_per_group = num_heads / num_kv_heads;
    const scale = 1.0 / @sqrt(@as(f32, @floatFromInt(head_dim)));
    const query_pos = kv_tokens - 1;
    for (0..num_heads) |head| {
        const kv_head = head / heads_per_group;
        var scores: [kv_tokens]f32 = undefined;
        var best: f32 = -std.math.inf(f32);
        for (0..kv_tokens) |token| {
            const allowed = query_pos >= token and query_pos - token < sliding_window;
            if (!allowed) {
                scores[token] = -std.math.inf(f32);
                continue;
            }
            var dot: f32 = 0.0;
            for (0..head_dim) |col| {
                const k_half: f16 = @floatCast(k_data[token * kv_dim + kv_head * head_dim + col]);
                const k_value: f32 = @floatCast(k_half);
                dot += q_data[head * head_dim + col] * k_value;
            }
            const score = dot * scale;
            scores[token] = score;
            best = @max(best, score);
        }
        var denom: f32 = 0.0;
        for (&scores) |*score| {
            score.* = if (std.math.isFinite(score.*)) @exp(score.* - best) else 0.0;
            denom += score.*;
        }
        const inv_denom = if (denom > 0.0) 1.0 / denom else 0.0;
        for (0..head_dim) |col| {
            var acc: f32 = 0.0;
            for (0..kv_tokens) |token| {
                const v_half: f16 = @floatCast(v_data[token * kv_dim + kv_head * head_dim + col]);
                const v_value: f32 = @floatCast(v_half);
                acc += scores[token] * inv_denom * v_value;
            }
            expected[head * head_dim + col] = acc;
        }
    }

    var out_mut = out;
    const actual = try tensorHostSlice(&out_mut);
    try std.testing.expectEqual(expected.len, actual.len);
    for (expected, actual, 0..) |exp, got, i| {
        if (!std.math.approxEqAbs(f32, exp, got, 1e-3)) {
            std.debug.print("paged f16 1x attention mismatch idx={d} expected={d} got={d}\n", .{ i, exp, got });
            return error.TestUnexpectedResult;
        }
    }

    const prior_tokens = kv_tokens - 1;
    var k_prior = try testDeviceTensorFromSlice(runtime, k_data[0 .. prior_tokens * kv_dim], &[_]i32{ @intCast(prior_tokens), @intCast(kv_dim) });
    defer k_prior.deinit();
    var v_prior = try testDeviceTensorFromSlice(runtime, v_data[0 .. prior_tokens * kv_dim], &[_]i32{ @intCast(prior_tokens), @intCast(kv_dim) });
    defer v_prior.deinit();
    var k_suffix = try testDeviceTensorFromSlice(runtime, k_data[prior_tokens * kv_dim .. kv_tokens * kv_dim], &[_]i32{ 1, @intCast(kv_dim) });
    defer k_suffix.deinit();
    var v_suffix = try testDeviceTensorFromSlice(runtime, v_data[prior_tokens * kv_dim .. kv_tokens * kv_dim], &[_]i32{ 1, @intCast(kv_dim) });
    defer v_suffix.deinit();
    var out_incremental = try MetalTensor.deviceAllocate(runtime, q_dim * @sizeOf(f32), .private, &[_]i32{ @intCast(q_len), @intCast(q_dim) });
    defer out_incremental.deinit();

    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_reset_attention_span_slot(runtime, 0));
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_update_attention_paged_from_f32_key_device_slot(
        runtime,
        0,
        f16_kv_format,
        k_prior.deviceHandle(),
        k_prior.deviceByteOffset(),
        v_prior.deviceHandle(),
        v_prior.deviceByteOffset(),
        prior_tokens,
        prior_tokens,
        num_kv_heads,
        head_dim,
        key_row_bytes,
        key_row_bytes,
        kv_dim,
        0,
        &block_offsets,
        block_offsets.len,
        page_size,
    ));
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_update_attention_paged_from_f32_key_device_slot(
        runtime,
        0,
        f16_kv_format,
        k_suffix.deviceHandle(),
        k_suffix.deviceByteOffset(),
        v_suffix.deviceHandle(),
        v_suffix.deviceByteOffset(),
        kv_tokens,
        1,
        num_kv_heads,
        head_dim,
        key_row_bytes,
        key_row_bytes,
        kv_dim,
        0,
        &block_offsets,
        block_offsets.len,
        page_size,
    ));
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_attention_paged_slot_device(
        runtime,
        0,
        f16_kv_format,
        q.deviceHandle(),
        q.deviceByteOffset(),
        &block_offsets,
        block_offsets.len,
        page_size,
        q_len,
        kv_tokens,
        num_heads,
        num_kv_heads,
        head_dim,
        key_row_bytes,
        key_row_bytes,
        kv_tokens - 1,
        0,
        sliding_window,
        0.0,
        null,
        0,
        out_incremental.deviceHandle(),
        out_incremental.deviceByteOffset(),
    ));
    var out_incremental_mut = out_incremental;
    const incremental_actual = try tensorHostSlice(&out_incremental_mut);
    try std.testing.expectEqual(expected.len, incremental_actual.len);
    for (expected, incremental_actual, 0..) |exp, got, i| {
        if (!std.math.approxEqAbs(f32, exp, got, 1e-3)) {
            std.debug.print("paged f16 incremental 1x attention mismatch idx={d} expected={d} got={d}\n", .{ i, exp, got });
            return error.TestUnexpectedResult;
        }
    }
}

test "metal native decoder runtime absolute embeddings" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;

    const tok_data = [_]f32{
        1.0,  2.0,  3.0,
        10.0, 20.0, 30.0,
    };
    const pos_data = [_]f32{
        0.5, 0.25, 0.125,
        1.0, 1.5,  2.0,
    };
    var tok = try MetalTensor.ownedCloneFrom(&tok_data, &[_]i32{ 2, 3 });
    defer tok.deinit();
    var pos = try MetalTensor.ownedCloneFrom(&pos_data, &[_]i32{ 2, 3 });
    defer pos.deinit();

    try std.testing.expect(try decoderRuntimePrepareAbsoluteEmbeddings(&provider, .{
        .token_embedding = tok,
        .position_embedding = pos,
        .vocab_size = 2,
        .max_position_embeddings = 2,
        .hidden_size = 3,
    }));

    var stats: ops.NativeQuantTimingStats = .{};
    var embedded = (try decoderRuntimeEmbedAbsolutePosition(&provider, .{
        .token_id = 1,
