    const suppress_two = [_]i32{ 3001, 17 };
    try std.testing.expectEqual(@as(usize, 1025), (try argmaxLogitsSuppressDevice(&provider, logits_tensor, out_dim, &suppress_two)) orelse return error.UnexpectedNull);
}

test "metal native top-p samplers can select the nucleus crossing token" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;

    // After max subtraction these logits produce weights [1, 0.5, 1/6]. At
    // top_p=0.8 the first token is insufficient, so the second token is the
    // nucleus crossing token and must remain selectable.
    const logits = [_]f32{ 0.0, @log(0.5), @log(1.0 / 6.0) };
    var logits_tensor = try testDeviceTensorFromSlice(runtime, &logits, &[_]i32{ 1, @intCast(logits.len) });
    defer logits_tensor.deinit();

    const SeedSearch = struct {
        fn sampleFraction(raw_seed: u32) f64 {
            var state = raw_seed ^ 0x9e3779b9;
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            return @as(f64, @floatFromInt(state)) / 4294967296.0;
        }
    };
    var seed: u32 = 0;
    while (SeedSearch.sampleFraction(seed) <= 0.75) : (seed += 1) {}

    // top_k=0 exercises the bounded serial sampler; top_k=3 exercises the
    // parallel top-k partials and reducer. With the old cutoff bug both paths
    // could only return token 0 for this distribution.
    for ([_]usize{ 0, logits.len }) |top_k| {
        var sampled_token: u32 = std.math.maxInt(u32);
        try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_sample_from_logits_device(
            runtime,
            logits_tensor.deviceHandle(),
            logits_tensor.deviceByteOffset(),
            logits.len,
            1.0,
            top_k,
            0.8,
            0.0,
            1.0,
            0.0,
            0.0,
            null,
            null,
            0,
            seed,
            &sampled_token,
        ));
        try std.testing.expectEqual(@as(u32, 1), sampled_token);
    }
}

test "metal native sampling preserves penalty histories larger than setBytes" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;

    const out_dim: usize = 1024;
    const penalty_count: usize = 600;
    const logits = try std.testing.allocator.alloc(f32, out_dim);
    defer std.testing.allocator.free(logits);
    @memset(logits, -100.0);
    logits[900] = 10.0;
    var logits_tensor = try testDeviceTensorFromSlice(runtime, logits, &[_]i32{ 1, @intCast(out_dim) });
    defer logits_tensor.deinit();

    const penalty_ids = try std.testing.allocator.alloc(u32, penalty_count);
    defer std.testing.allocator.free(penalty_ids);
    const penalty_counts = try std.testing.allocator.alloc(u32, penalty_count);
    defer std.testing.allocator.free(penalty_counts);
    for (0..penalty_count) |i| {
        penalty_ids[i] = @intCast(i);
        penalty_counts[i] = 1;
    }

    // Exercise both the parallel top-k and serial bounded samplers. A 600-entry
    // history is 4,800 bytes and therefore must bind through an MTLBuffer.
    for ([_]usize{ 64, 128 }) |top_k| {
        var sampled_token: u32 = std.math.maxInt(u32);
        try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_sample_from_logits_device(
            runtime,
            logits_tensor.deviceHandle(),
            logits_tensor.deviceByteOffset(),
            out_dim,
            0.0,
            top_k,
            1.0,
            0.0,
            1.1,
            0.0,
            0.0,
            &penalty_ids[0],
            &penalty_counts[0],
            penalty_count,
            1,
            &sampled_token,
        ));
        try std.testing.expectEqual(@as(u32, 900), sampled_token);
    }

    var unsupported_token: u32 = 0;
    try std.testing.expectEqual(@as(c_int, -3), termite_metal_decode_runtime_sample_from_logits_device(
        runtime,
        logits_tensor.deviceHandle(),
        logits_tensor.deviceByteOffset(),
        out_dim,
        1.0,
        257,
        1.0,
        0.0,
        1.0,
        0.0,
        0.0,
        null,
        null,
        0,
        1,
        &unsupported_token,
    ));
}

test "metal native decoder runtime batched multi-row argmax matches per-row" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;

    // dim >= 2048 exercises the parallel partials+reduce path; each row has a
    // distinct maximum so a scratch/token offset bug cross-contaminates rows.
    const dim: usize = 4096;
    const rows: usize = 5;
    const maxima = [_]usize{ 7, 4095, 1234, 2048, 0 };
    const logits = try std.testing.allocator.alloc(f32, rows * dim);
    defer std.testing.allocator.free(logits);
    for (0..rows) |row| {
        const row_data = logits[row * dim ..][0..dim];
        for (row_data, 0..) |*v, i| v.* = -100.0 - @as(f32, @floatFromInt(i % 97));
        row_data[maxima[row]] = 50.0 + @as(f32, @floatFromInt(row));
        // A decoy second-best for the suppression check.
        row_data[(maxima[row] + 11) % dim] = 40.0;
    }
    var logits_tensor = try testDeviceTensorFromSlice(runtime, logits, &[_]i32{ @intCast(rows), @intCast(dim) });
    defer logits_tensor.deinit();

    // All rows, no suppression.
    var tokens: [rows]u32 = undefined;
    try std.testing.expect(try argmaxLogitsRowsSuppressDevice(&provider, logits_tensor, 0, dim, &.{}, tokens[0..rows]));
    for (0..rows) |row| try std.testing.expectEqual(@as(u32, @intCast(maxima[row])), tokens[row]);

    // Nonzero row_start: rows 2..5 only.
    var tail_tokens: [3]u32 = undefined;
    try std.testing.expect(try argmaxLogitsRowsSuppressDevice(&provider, logits_tensor, 2, dim, &.{}, tail_tokens[0..3]));
    for (0..3) |i| try std.testing.expectEqual(@as(u32, @intCast(maxima[2 + i])), tail_tokens[i]);

    // Suppression: suppress every row's max -> each row falls to its decoy.
    const suppress = [_]i32{ 7, 4095, 1234, 2048, 0 };
    var suppressed: [rows]u32 = undefined;
    try std.testing.expect(try argmaxLogitsRowsSuppressDevice(&provider, logits_tensor, 0, dim, &suppress, suppressed[0..rows]));
    for (0..rows) |row| try std.testing.expectEqual(@as(u32, @intCast((maxima[row] + 11) % dim)), suppressed[row]);

    // Small dim exercises the serial single-thread kernel path.
    const small_dim: usize = 64;
    const small_rows: usize = 3;
    const small_maxima = [_]usize{ 5, 63, 31 };
    var small_logits: [small_rows * small_dim]f32 = undefined;
    for (0..small_rows) |row| {
        const row_data = small_logits[row * small_dim ..][0..small_dim];
        for (row_data) |*v| v.* = -5.0;
        row_data[small_maxima[row]] = 9.0;
    }
    var small_tensor = try testDeviceTensorFromSlice(runtime, &small_logits, &[_]i32{ @intCast(small_rows), @intCast(small_dim) });
    defer small_tensor.deinit();
    var small_tokens: [small_rows]u32 = undefined;
    try std.testing.expect(try argmaxLogitsRowsSuppressDevice(&provider, small_tensor, 0, small_dim, &.{}, small_tokens[0..small_rows]));
    for (0..small_rows) |row| try std.testing.expectEqual(@as(u32, @intCast(small_maxima[row])), small_tokens[row]);

    // The generic helper preserves its historical frame lifecycle.
    try std.testing.expect(reserveArgmaxRows(&provider, rows, dim));
    try beginFrame(runtime);
    defer if (hasActiveFrame(runtime)) cancelFrame(runtime) catch {};
    try beginPlannedComputeScope(runtime, @intFromEnum(ComputeSource.tail), .tail);
    var generic_frame_tokens: [rows]u32 = undefined;
    try std.testing.expect(try argmaxLogitsRowsSuppressDevice(&provider, logits_tensor, 0, dim, &suppress, generic_frame_tokens[0..rows]));
    for (0..rows) |row| try std.testing.expectEqual(@as(u32, @intCast((maxima[row] + 11) % dim)), generic_frame_tokens[row]);
    try std.testing.expect(hasActiveFrame(runtime));
    try cancelFrame(runtime);

    // The explicit tail helper consumes the planned frame in one submit/wait.
    try beginFrame(runtime);
    try beginPlannedComputeScope(runtime, @intFromEnum(ComputeSource.tail), .tail);
    var frame_tokens: [rows]u32 = undefined;
    try std.testing.expect(try argmaxLogitsRowsSuppressDeviceConsumeActiveFrame(&provider, logits_tensor, 0, dim, &suppress, frame_tokens[0..rows]));
    for (0..rows) |row| try std.testing.expectEqual(@as(u32, @intCast((maxima[row] + 11) % dim)), frame_tokens[row]);
    try std.testing.expect(!hasActiveFrame(runtime));
}

test "A4B Metal Q4_0 expert slot arena matches dequantized routed FFN" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const layer: usize = 2;
    const hidden: usize = 32;
    const inter: usize = 32;
    const num_experts: usize = 4;
    const top_k: usize = 2;
    const slot_count: usize = 2;
    const projection_values = hidden * inter;
    const projection_bytes = inter * (hidden / 32) * 18;
    const gate_offset: usize = 0;
    const up_offset = projection_bytes;
    const down_offset = projection_bytes * 2;
    const expert_stride: usize = 16 * 1024;

    const slot_images = try allocator.alloc(u8, slot_count * expert_stride);
    defer allocator.free(slot_images);
    @memset(slot_images, 0);
    var dequantized = [_][3][projection_values]f32{
        [_][projection_values]f32{[_]f32{0} ** projection_values} ** 3,
    } ** slot_count;
    const diagonal_scales = [_][3]f32{
        .{ 0.5, 1.0, 1.0 },
        .{ 1.0, 0.25, 2.0 },
    };
    const offsets = [_]usize{ gate_offset, up_offset, down_offset };
    for (0..slot_count) |slot| {
        for (0..3) |projection| {
            var dense = [_]f32{0} ** projection_values;
            for (0..hidden) |row| {
                dense[row * hidden + row] = diagonal_scales[slot][projection];
                dense[row * hidden + (row + 7) % hidden] = diagonal_scales[slot][projection] * 0.125;
            }
            const encoded = try quant_codec.quantizeQ4_0FromF32(allocator, &dense);
            defer allocator.free(encoded);
            try std.testing.expectEqual(projection_bytes, encoded.len);
            const destination = slot * expert_stride + offsets[projection];
            @memcpy(slot_images[destination..][0..projection_bytes], encoded);
            try quant_codec.dequantizeToFloat32(.{ .known = .Q4_0 }, encoded, &dequantized[slot][projection]);
        }
    }

    const input_data = [_]f32{
        0.25,   -0.5,    0.75,   -1.0,    0.125,  -0.25,   0.5,    -0.75,
        1.0,    -0.125,  0.375,  -0.625,  0.875,  -1.125,  0.2,    -0.4,
        0.6,    -0.8,    1.2,    -1.4,    0.3,    -0.6,    0.9,    -1.2,
        0.0625, -0.1875, 0.3125, -0.4375, 0.5625, -0.6875, 0.8125, -0.9375,
    };
    const logits_data = [_]f32{ 0.0, 3.0, 0.5, 2.0 };
    var input = try testDeviceTensorFromSlice(runtime, &input_data, &[_]i32{ 1, hidden });
    defer input.deinit();
    var logits = try testDeviceTensorFromSlice(runtime, &logits_data, &[_]i32{ 1, num_experts });
    defer logits.deinit();

    var slot_map = [_]u32{std.math.maxInt(u32)} ** num_experts;
    slot_map[1] = 0;
    slot_map[3] = 1;
    const uploaded_slots = [_]u32{ 0, 1 };
    var expected: [hidden]f32 = undefined;
    const counters_before = runtimeMemorySnapshot(runtime);

    for (0..2) |pass| {
        var route_ids: [top_k]u32 = undefined;
        var route_weights: [top_k]f32 = undefined;
        try beginFrame(runtime);
        errdefer if (hasActiveFrame(runtime)) cancelFrame(runtime) catch {};
        try std.testing.expect(try decoderRuntimeSelectMoeRoutesDevice(
            &provider,
            layer,
            logits,
            1,
            num_experts,
            top_k,
            1.0,
            &route_ids,
            &route_weights,
        ));
        try std.testing.expectEqualSlices(u32, &.{ 1, 3 }, &route_ids);
        if (pass == 0) {
            try std.testing.expect(decoderRuntimePrepareMoeQ4_0SlotArena(
                &provider,
                layer,
                slot_count,
                expert_stride,
                gate_offset,
                up_offset,
                down_offset,
                hidden,
                inter,
            ));
            try std.testing.expect(decoderRuntimePublishMoeExpertSlotMap(&provider, layer, &slot_map));
            try std.testing.expect(decoderRuntimeUploadMoeQ4_0Slots(
                &provider,
                layer,
                &uploaded_slots,
                slot_images,
                expert_stride,
            ));
        }
        var output = (try decoderRuntimeMoeForwardQ4_0SlotsDevice(
            &provider,
            layer,
            input,
            1,
            hidden,
            inter,
            num_experts,
            top_k,
            .gelu_new,
            null,
        )) orelse return error.UnexpectedNull;
        defer output.deinit();
        try submitFrame(runtime);
        try waitFrame(runtime);

        @memset(&expected, 0);
        for (0..top_k) |route| {
            const slot: usize = if (route_ids[route] == 1) 0 else 1;
            var gate: [inter]f32 = undefined;
            var up: [inter]f32 = undefined;
            for (0..inter) |row| {
                gate[row] = 0;
                up[row] = 0;
                for (0..hidden) |column| {
                    gate[row] += input_data[column] * dequantized[slot][0][row * hidden + column];
                    up[row] += input_data[column] * dequantized[slot][1][row * hidden + column];
                }
            }
            applyActivationHost(&gate, .gelu_new);
            for (&gate, up) |*gate_value, up_value| gate_value.* *= up_value;
            for (0..hidden) |row| {
                var down: f32 = 0;
                for (0..inter) |column| down += gate[column] * dequantized[slot][2][row * inter + column];
                expected[row] += down * route_weights[route];
            }
        }
        var output_mut = output;
        const actual = try tensorHostSlice(&output_mut);
        for (expected, actual, 0..) |want, got, index| {
            if (!std.math.approxEqAbs(f32, want, got, 2e-3)) {
                std.debug.print("A4B slot arena mismatch pass={d} index={d} expected={d} got={d}\n", .{ pass, index, want, got });
                return error.TestUnexpectedResult;
            }
        }
    }
    const counters_after = runtimeMemorySnapshot(runtime);
    try std.testing.expectEqual(counters_before.moe_slot_arena_attempt_count + 2, counters_after.moe_slot_arena_attempt_count);
    try std.testing.expectEqual(counters_before.moe_slot_arena_success_count + 2, counters_after.moe_slot_arena_success_count);
    try std.testing.expectEqual(counters_before.moe_slot_map_publication_attempt_count + 1, counters_after.moe_slot_map_publication_attempt_count);
    try std.testing.expectEqual(counters_before.moe_slot_map_publication_success_count + 1, counters_after.moe_slot_map_publication_success_count);
    try std.testing.expectEqual(counters_before.moe_slot_upload_batch_count + 1, counters_after.moe_slot_upload_batch_count);
    try std.testing.expectEqual(counters_before.moe_slot_upload_count + @as(u64, @intCast(uploaded_slots.len)), counters_after.moe_slot_upload_count);
    try std.testing.expectEqual(counters_before.moe_slot_upload_bytes + @as(u64, @intCast(slot_images.len)), counters_after.moe_slot_upload_bytes);
}

const MappedSelectedExpertPageSpan = struct {
    first_page_offset: usize,
    page_count: usize,
};

// Mirrors the device kernel's page-range arithmetic. Keeping this overflow-
// checked oracle next to the Metal parity test makes the head/tail-page
// contract explicit without adding a route readback to the runtime.
fn mappedSelectedExpertPageSpan(
    weight_view_offset: usize,
    expert: usize,
    source_out_dim: usize,
    row_offset: usize,
    logical_out_dim: usize,
    row_stride: usize,
    page_size: usize,
) ?MappedSelectedExpertPageSpan {
    if (logical_out_dim == 0 or row_stride == 0 or page_size == 0) return null;
    const expert_row = std.math.mul(usize, expert, source_out_dim) catch return null;
    const first_row = std.math.add(usize, expert_row, row_offset) catch return null;
    const row_byte_offset = std.math.mul(usize, first_row, row_stride) catch return null;
    const span_start = std.math.add(usize, weight_view_offset, row_byte_offset) catch return null;
    const span_bytes = std.math.mul(usize, logical_out_dim, row_stride) catch return null;
    const span_end = std.math.add(usize, span_start, span_bytes) catch return null;
    const first_page_index = span_start / page_size;
    const end_page_index = (span_end - 1) / page_size + 1;
    return .{
        .first_page_offset = first_page_index * page_size,
        .page_count = end_page_index - first_page_index,
    };
}

test "A4B Metal selected expert mapped-page accounting covers exact logical spans" {
    const page_size: usize = 16 * 1024;
    const hidden: usize = 2816;
    const inter: usize = 704;
    const top_k: usize = 8;
    const gate_row_stride = (hidden / 32) * 18;
    const down_row_stride = (inter / 32) * 18;
    const gate_expert_bytes = inter * gate_row_stride;
    const down_expert_bytes = hidden * down_row_stride;
    try std.testing.expectEqual(@as(usize, 1_115_136), gate_expert_bytes);
    try std.testing.expectEqual(gate_expert_bytes, down_expert_bytes);
    try std.testing.expectEqual(@as(usize, 26_763_264), top_k * (2 * gate_expert_bytes + down_expert_bytes));

    const aligned = mappedSelectedExpertPageSpan(0, 15, inter, 0, inter, gate_row_stride, page_size) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 69), aligned.page_count);

    // A 32-byte mmap-view head shifts every sixteenth expert across one more
    // physical page. The device dispatch uses the 70-page upper bound and its
    // range guard reduces this selected set to exactly 556 touches.
    const selected_ids = [_]usize{ 0, 15, 16, 31, 32, 47, 48, 127 };
    var selected_page_touches: usize = 0;
    for (selected_ids) |expert| {
        const span = mappedSelectedExpertPageSpan(32, expert, inter, 0, inter, gate_row_stride, page_size) orelse
            return error.TestUnexpectedResult;
        selected_page_touches += span.page_count;
        try std.testing.expect(span.first_page_offset <= 32 + expert * gate_expert_bytes);
    }
    try std.testing.expectEqual(@as(usize, 556), selected_page_touches);
    try std.testing.expectEqual(@as(usize, 12), 3 * top_k * 70 - 3 * selected_page_touches);

    // Fused packed tensors may expose the logical gate/up half through a row
    // offset; it must still cover only one expert projection, not both halves.
    const fused_half = mappedSelectedExpertPageSpan(
        0,
        0,
        inter * 2,
        inter,
        inter,
        gate_row_stride,
        page_size,
    ) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 69), fused_half.page_count);
}

test "A4B Metal device-mapped Q4_0 MoE streams nonzero layer without residency" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const hidden: usize = 32;
    const inter: usize = 32;
    const num_experts: usize = 4;
    const top_k: usize = 2;
    const projection_values = hidden * inter;
    const projection_bytes = inter * (hidden / 32) * 18;
    const packed_bytes = num_experts * projection_bytes;
    const merged_gate_up_bytes = packed_bytes * 2;

    const gate_up_page = try std.heap.page_allocator.alloc(u8, std.heap.page_size_min);
    defer std.heap.page_allocator.free(gate_up_page);
    const down_page = try std.heap.page_allocator.alloc(u8, std.heap.page_size_min);
    defer std.heap.page_allocator.free(down_page);
    @memset(gate_up_page, 0);
    @memset(down_page, 0);

    var dequantized = [_][num_experts][projection_values]f32{
        [_][projection_values]f32{[_]f32{0} ** projection_values} ** num_experts,
    } ** 3;
    const diagonal_scales = [_][num_experts]f32{
        .{ 0.25, 0.5, 0.75, 1.0 },
        .{ 1.0, 0.5, 0.25, 0.125 },
        .{ 0.5, 1.0, 1.5, 2.0 },
    };
    for (0..3) |projection| {
        for (0..num_experts) |expert| {
            var dense = [_]f32{0} ** projection_values;
            const scale = diagonal_scales[projection][expert];
            for (0..hidden) |row| {
                dense[row * hidden + row] = scale;
                dense[row * hidden + (row + expert + 3) % hidden] = scale * 0.125;
            }
            const encoded = try quant_codec.quantizeQ4_0FromF32(allocator, &dense);
            defer allocator.free(encoded);
            try std.testing.expectEqual(projection_bytes, encoded.len);
            const raw_offset = if (projection < 2)
                (expert * 2 + projection) * projection_bytes
            else
                expert * projection_bytes;
            const raw = if (projection < 2) gate_up_page else down_page;
            @memcpy(raw[raw_offset..][0..projection_bytes], encoded);
            try quant_codec.dequantizeToFloat32(
                .{ .known = .Q4_0 },
                encoded,
                &dequantized[projection][expert],
            );
        }
    }

    const input_data = [_]f32{
        0.25,   -0.5,    0.75,   -1.0,    0.125,  -0.25,   0.5,    -0.75,
        1.0,    -0.125,  0.375,  -0.625,  0.875,  -1.125,  0.2,    -0.4,
        0.6,    -0.8,    1.2,    -1.4,    0.3,    -0.6,    0.9,    -1.2,
        0.0625, -0.1875, 0.3125, -0.4375, 0.5625, -0.6875, 0.8125, -0.9375,
    };
    const logits_data = [_]f32{ 0.0, 3.0, 0.5, 2.0 };
    var input = try testDeviceTensorFromSlice(runtime, &input_data, &[_]i32{ 1, hidden });
    defer input.deinit();
    var logits = try testDeviceTensorFromSlice(runtime, &logits_data, &[_]i32{ 1, num_experts });
    defer logits.deinit();

    // Exercise the selected-page lane before any whole-tensor linear slot has
    // been prepared.  Only the compact route IDs cross to the host.
    var selected_route_ids: [top_k]u32 = undefined;
    var selected_route_weights: [top_k]f32 = undefined;
    try std.testing.expect(try decoderRuntimeSelectMoeRoutesDevice(
        &provider,
        1,
        logits,
        1,
        num_experts,
        top_k,
        1.0,
        &selected_route_ids,
        &selected_route_weights,
    ));
    try std.testing.expectEqualSlices(u32, &[_]u32{ 1, 3 }, &selected_route_ids);
    try beginFrame(runtime);
    errdefer if (hasActiveFrame(runtime)) cancelFrame(runtime) catch {};
    const merged_source = MappedMoeProjectionSource{
        .mapped_base = gate_up_page.ptr,
        .mapped_bytes = gate_up_page.len,
        .weight_offset = 0,
        .weight_bytes = merged_gate_up_bytes,
        .row_stride = (hidden / 32) * 18,
        .source_out_dim = inter * 2,
        .row_offset = 0,
        .expert_count = num_experts,
    };
    const up_source = MappedMoeProjectionSource{
        .mapped_base = gate_up_page.ptr,
        .mapped_bytes = gate_up_page.len,
        .weight_offset = 0,
        .weight_bytes = merged_gate_up_bytes,
        .row_stride = (hidden / 32) * 18,
        .source_out_dim = inter * 2,
        .row_offset = inter,
        .expert_count = num_experts,
    };
    const down_source = MappedMoeProjectionSource{
        .mapped_base = down_page.ptr,
        .mapped_bytes = down_page.len,
        .weight_offset = 0,
        .weight_bytes = packed_bytes,
        .row_stride = (inter / 32) * 18,
        .source_out_dim = hidden,
        .row_offset = 0,
        .expert_count = num_experts,
    };
    try std.testing.expect(mappedMoeProjectionSourcesCanFuse(merged_source, up_source, inter));
    const memory_before_selected = runtimeMemorySnapshot(runtime);
    var selected_result = (try decoderRuntimeMoeForwardQ4_0SelectedPagesDevice(
        &provider,
        1,
        merged_source,
        up_source,
        down_source,
        &selected_route_ids,
        input,
        1,
        hidden,
        inter,
        num_experts,
        top_k,
        .gelu_new,
        true,
        null,
    )) orelse return error.UnexpectedNull;
    defer selected_result.output.deinit();
    try std.testing.expectEqual(@as(u64, top_k * (merged_gate_up_bytes / num_experts + packed_bytes / num_experts)), selected_result.logical_weight_bytes);
    try std.testing.expectEqual(@as(u64, top_k * 2), selected_result.allocation_count);
    try std.testing.expectEqual(@as(u64, top_k * 2 * std.heap.page_size_min), selected_result.mapped_page_bytes);
    try submitFrame(runtime);
    try waitFrame(runtime);
    const memory_after_selected = runtimeMemorySnapshot(runtime);
    try std.testing.expectEqual(
        memory_before_selected.mapped_moe_residency_allocation_count,
        memory_after_selected.mapped_moe_residency_allocation_count,
    );
    try std.testing.expectEqual(@as(u64, 0), memory_after_selected.frame_retained_bytes);

    const gate_slot = decoder_runtime_linear_slot_capacity - 3;
    const up_slot = decoder_runtime_linear_slot_capacity - 2;
    const down_slot = decoder_runtime_linear_slot_capacity - 1;
    for ([_]struct { slot: usize, page: []u8, weight_bytes: usize, flat_out_dim: usize }{
        .{ .slot = gate_slot, .page = gate_up_page, .weight_bytes = merged_gate_up_bytes, .flat_out_dim = num_experts * inter * 2 },
        .{ .slot = up_slot, .page = gate_up_page, .weight_bytes = merged_gate_up_bytes, .flat_out_dim = num_experts * inter * 2 },
        .{ .slot = down_slot, .page = down_page, .weight_bytes = packed_bytes, .flat_out_dim = num_experts * inter },
    }) |projection| {
        try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_prepare_quantized_linear_slot_no_copy_region(
            runtime,
            @intFromEnum(MetalQuantFormat.q4_0),
            projection.slot,
            projection.page.ptr,
            projection.page.len,
            0,
            projection.weight_bytes,
            hidden,
            projection.flat_out_dim,
        ));
    }

    const gate_descriptor = PackedMoeLinearDescriptor{
        .slot = gate_slot,
        .format = .q4_0,
        .source_out_dim = inter * 2,
        .row_offset = 0,
        .expert_count = num_experts,
    };
    const up_descriptor = PackedMoeLinearDescriptor{
        .slot = up_slot,
        .format = .q4_0,
        .source_out_dim = inter * 2,
        .row_offset = inter,
        .expert_count = num_experts,
    };
    const down_descriptor = PackedMoeLinearDescriptor{
        .slot = down_slot,
        .format = .q4_0,
        .source_out_dim = hidden,
        .row_offset = 0,
        .expert_count = num_experts,
    };
    try std.testing.expect(decoderRuntimePrewarmMappedMoeLayer0(
        &provider,
        1,
        gate_descriptor,
        up_descriptor,
        down_descriptor,
        hidden,
        inter,
        num_experts,
    ) == null);
    const prewarm = decoderRuntimePrewarmMappedMoeLayer0(
        &provider,
        0,
        gate_descriptor,
        up_descriptor,
        down_descriptor,
        hidden,
        inter,
        num_experts,
    ) orelse return error.UnexpectedNull;
    try std.testing.expectEqual(@as(u64, 2 * merged_gate_up_bytes + packed_bytes), prewarm.logical_bytes);
    try std.testing.expectEqual(@as(u64, 3), prewarm.page_touches);

    try std.testing.expect(!decoderRuntimeSelectMoeRoutesBufferedDevice(
        &provider,
        0,
        logits,
        1,
        num_experts,
        top_k,
        1.0,
    ));
    try beginFrame(runtime);
    errdefer if (hasActiveFrame(runtime)) cancelFrame(runtime) catch {};
    try std.testing.expect(decoderRuntimeSelectMoeRoutesBufferedDevice(
        &provider,
        1,
        logits,
        1,
        num_experts,
        top_k,
        1.0,
    ));
    try std.testing.expect(decoderRuntimePrewarmMappedMoeLayer0(
        &provider,
        0,
        gate_descriptor,
        up_descriptor,
        down_descriptor,
        hidden,
        inter,
        num_experts,
    ) == null);
    try std.testing.expect((try decoderRuntimeMoeForwardQ4_0MappedLayer0Device(
        &provider,
        1,
        gate_descriptor,
        up_descriptor,
        down_descriptor,
        input,
        1,
        hidden,
        inter,
        num_experts,
        top_k,
        .gelu_new,
        false,
        null,
    )) == null);
    const memory_before_streamed = runtimeMemorySnapshot(runtime);
    var output = (try decoderRuntimeMoeForwardQ4_0MappedDevice(
        &provider,
        1,
        gate_descriptor,
        up_descriptor,
        down_descriptor,
        input,
        1,
        hidden,
        inter,
        num_experts,
        top_k,
        .gelu_new,
        false,
        .streamed,
        true,
        null,
    )) orelse return error.UnexpectedNull;
    defer output.deinit();
    // Streamed callers release their bounded descriptor bindings as soon as
    // encoding finishes. The command buffer must retain the resources needed
    // by the already encoded dispatch through submission and completion.
    clearRawLinearSlot(&provider, gate_slot);
    clearRawLinearSlot(&provider, up_slot);
    clearRawLinearSlot(&provider, down_slot);
    try submitFrame(runtime);
    try waitFrame(runtime);
    const memory_after_streamed = runtimeMemorySnapshot(runtime);
    try std.testing.expectEqual(
        memory_before_streamed.mapped_moe_residency_allocation_count,
        memory_after_streamed.mapped_moe_residency_allocation_count,
    );
    try std.testing.expectEqual(
        memory_before_streamed.mapped_moe_residency_commit_count,
        memory_after_streamed.mapped_moe_residency_commit_count,
    );
    try std.testing.expectEqual(
        memory_before_streamed.mapped_moe_residency_request_count,
        memory_after_streamed.mapped_moe_residency_request_count,
    );
    try std.testing.expectEqual(
        memory_before_streamed.mapped_moe_fused_gate_up_dispatches + 2,
        memory_after_streamed.mapped_moe_fused_gate_up_dispatches,
    );

    const route_ids = [_]usize{ 1, 3 };
    const first_weight = @exp(@as(f32, 3.0));
    const second_weight = @exp(@as(f32, 2.0));
    const route_weights = [_]f32{
        first_weight / (first_weight + second_weight),
        second_weight / (first_weight + second_weight),
    };
    var expected = [_]f32{0} ** hidden;
    for (route_ids, route_weights) |expert, route_weight| {
        var gate = [_]f32{0} ** inter;
        var up = [_]f32{0} ** inter;
        for (0..inter) |row| {
            for (0..hidden) |column| {
                gate[row] += input_data[column] * dequantized[0][expert][row * hidden + column];
                up[row] += input_data[column] * dequantized[1][expert][row * hidden + column];
            }
        }
        applyActivationHost(&gate, .gelu_new);
        for (&gate, up) |*gate_value, up_value| gate_value.* *= up_value;
        for (0..hidden) |row| {
            var down: f32 = 0;
            for (0..inter) |column| {
                down += gate[column] * dequantized[2][expert][row * inter + column];
            }
            expected[row] += down * route_weight;
        }
    }

    var output_mut = output;
    const actual = try tensorHostSlice(&output_mut);
    for (expected, actual, 0..) |want, got, index| {
        if (!std.math.approxEqAbs(f32, want, got, 2e-3)) {
            std.debug.print("A4B streamed mapped mismatch index={d} expected={d} got={d}\n", .{ index, want, got });
            return error.TestUnexpectedResult;
        }
    }
    const selected_actual = try tensorHostSlice(&selected_result.output);
    for (expected, selected_actual, 0..) |want, got, index| {
        if (!std.math.approxEqAbs(f32, want, got, 2e-3)) {
            std.debug.print("A4B selected-page mismatch index={d} expected={d} got={d}\n", .{ index, want, got });
            return error.TestUnexpectedResult;
        }
    }
}

test "metal native decoder runtime can prepare bf16 linear without copying model-owned bytes" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;

    const hidden_size: usize = 4;
    const out_dim: usize = 3;
    const bf16_weight_words = [_]u16{
        0x3f80, 0x0000, 0x0000, 0x0000,
        0x0000, 0x3f80, 0x0000, 0x0000,
        0x3f00, 0x3f00, 0x3f00, 0x3f00,
    };
    const bf16_weight_bytes = std.mem.sliceAsBytes(&bf16_weight_words);
    const bias_data = [_]f32{ 0.0, 0.0, 0.0 };
    var linear_bias = try MetalTensor.ownedCloneFrom(&bias_data, &[_]i32{@intCast(out_dim)});
    defer linear_bias.deinit();

    var dummy_weight_value = [_]f32{0.0};
    const dummy_weight = MetalTensor.borrowed(dummy_weight_value[0..].ptr, 1, &[_]i32{0});
    var prep_stats: ops.NativeQuantTimingStats = .{};
    try std.testing.expect(try decoderRuntimePrepareLinear(&provider, .{
        .slot = 0,
        .weight = dummy_weight,
        .bias = linear_bias,
        .quantized_storage = null,
        .in_dim = hidden_size,
        .out_dim = out_dim,
        .retain_dense_fallback = false,
        .dense_bf16_bytes = bf16_weight_bytes,
        .dense_bf16_no_copy_safe = true,
    }, &prep_stats));

    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;
    const input_data = [_]f32{ 1.0, -2.0, 0.5, 3.0 };
    var input = try testDeviceTensorFromSlice(runtime, &input_data, &[_]i32{ 1, @intCast(hidden_size) });
    defer input.deinit();

    var output = (try decoderRuntimeApplyLinear(&provider, .{
        .slot = 0,
        .input = input,
        .in_dim = hidden_size,
        .out_dim = out_dim,
    })) orelse return error.UnexpectedNull;
    defer output.deinit();

    var output_mut = output;
    const actual = try tensorHostSlice(&output_mut);
    try std.testing.expectEqual(@as(usize, out_dim), actual.len);
    try std.testing.expectApproxEqAbs(@as(f32, 1.0), actual[0], 1e-3);
    try std.testing.expectApproxEqAbs(@as(f32, -2.0), actual[1], 1e-3);
    try std.testing.expectApproxEqAbs(@as(f32, 1.25), actual[2], 1e-3);
}

test "metal native decoder runtime f16 linear matches host reference" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;

    const hidden_size: usize = 32;
    const out_dim: usize = 3;
    var dense_weight = [_]f32{0.0} ** (hidden_size * out_dim);
    dense_weight[0] = 1.0;
    dense_weight[hidden_size + 1] = 1.0;
    for (0..4) |index| dense_weight[2 * hidden_size + index] = 0.5;
    const q4_bytes = try quant_codec.quantizeQ4_0FromF32(std.testing.allocator, &dense_weight);
    defer std.testing.allocator.free(q4_bytes);
    const shape = [_]i64{ @intCast(out_dim), @intCast(hidden_size) };
    const storage = QuantizedStorage{
        .tensor_type = .{ .known = .Q4_0 },
        .raw_bytes = q4_bytes,
        .shape = &shape,
        .raw_owned = false,
        .allocator = std.testing.allocator,
    };
    const bias = [_]f32{ 0.0, 0.0, 0.0 };
    var linear_bias = try MetalTensor.ownedCloneFrom(&bias, &[_]i32{@intCast(out_dim)});
    defer linear_bias.deinit();
    var dummy_weight_value = [_]f32{0.0};
    const dummy_weight = MetalTensor.borrowed(dummy_weight_value[0..].ptr, 1, &[_]i32{0});
    var prep_stats: ops.NativeQuantTimingStats = .{};
    try std.testing.expect(try decoderRuntimePrepareLinear(&provider, .{
        .slot = 0,
        .weight = dummy_weight,
        .bias = linear_bias,
        .quantized_storage = @as(?*const QuantizedStorage, &storage),
        .in_dim = hidden_size,
        .out_dim = out_dim,
        .retain_dense_fallback = true,
        .dense_fallback_max_bytes = @as(?usize, 1024),
        .allow_direct_quant_fallback = true,
        .prefer_f16_mps_fallback = true,
    }, &prep_stats));

    var input = [_]f32{0.0} ** hidden_size;
    input[0] = 1.0;
    input[1] = -2.0;
    input[2] = 0.5;
    input[3] = 3.0;
    var output: [out_dim]f32 = undefined;
    try std.testing.expect(try tryRawLinearHost(
        &provider,
        0,
        &input,
        hidden_size,
        out_dim,
        &output,
    ));
    var dequantized: [hidden_size * out_dim]f32 = undefined;
    try quant_codec.dequantizeToFloat32(storage.tensor_type, storage.raw_bytes, &dequantized);
    for (0..out_dim) |row| {
        var expected: f32 = 0.0;
        for (0..hidden_size) |column| expected += input[column] * dequantized[row * hidden_size + column];
        try std.testing.expectApproxEqAbs(expected, output[row], 1e-3);
    }
}

test "metal native decoder runtime f16 BERT fused paths match decomposed device ops" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;
    if (getenvBool("TERMITE_METAL_DISABLE_DENSE_QKV_PACKED")) return error.SkipZigTest;
    if ((getenvUsize("TERMITE_METAL_DENSE_QKV_PACK_CACHE_MAX_MB") orelse 256) == 0) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;

    const allocator = std.testing.allocator;
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;
    const rows: usize = 4;
    const hidden: usize = 64;
    const intermediate: usize = 128;

    const Compare = struct {
        fn close(label: []const u8, expected: []const f32, actual: []const f32) !void {
            try std.testing.expectEqual(expected.len, actual.len);
            for (expected, actual, 0..) |want, got, index| {
                if (!std.math.isFinite(got) or !std.math.approxEqAbs(f32, want, got, 3e-3)) {
                    std.debug.print("{s} mismatch index={} expected={d} actual={d}\n", .{ label, index, want, got });
                    return error.TestUnexpectedResult;
                }
            }
        }

        fn prepareLinear(
            p: anytype,
            slot: usize,
            storage: *const QuantizedStorage,
            bias: MetalTensor,
            in_dim: usize,
            out_dim: usize,
            stats: *ops.NativeQuantTimingStats,
        ) !void {
            var dummy_value = [_]f32{0};
            const dummy = MetalTensor.borrowed(&dummy_value, 1, &[_]i32{0});
            try std.testing.expect(try decoderRuntimePrepareLinear(p, .{
                .slot = slot,
                .weight = dummy,
                .bias = bias,
                .quantized_storage = @as(?*const QuantizedStorage, storage),
                .in_dim = in_dim,
                .out_dim = out_dim,
                .retain_dense_fallback = true,
                .dense_fallback_max_bytes = @as(?usize, 1024 * 1024),
                .allow_direct_quant_fallback = true,
                .prefer_f16_mps_fallback = true,
            }, stats));
        }
    };

    const identity_values = try allocator.alloc(f32, hidden * hidden);
    defer allocator.free(identity_values);
    @memset(identity_values, 0);
    for (0..hidden) |index| identity_values[index * hidden + index] = 1;
    const identity_q4 = try quant_codec.quantizeQ4_0FromF32(allocator, identity_values);
    defer allocator.free(identity_q4);
    const identity_shape = [_]i64{ hidden, hidden };
    const identity_storage = QuantizedStorage{
        .tensor_type = .{ .known = .Q4_0 },
        .raw_bytes = identity_q4,
        .shape = &identity_shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    const up_values = try allocator.alloc(f32, intermediate * hidden);
    defer allocator.free(up_values);
    @memset(up_values, 0);
    for (0..hidden) |index| {
        up_values[index * hidden + index] = 1;
        up_values[(hidden + index) * hidden + index] = -0.5;
    }
    const up_q4 = try quant_codec.quantizeQ4_0FromF32(allocator, up_values);
    defer allocator.free(up_q4);
    const up_shape = [_]i64{ intermediate, hidden };
    const up_storage = QuantizedStorage{
        .tensor_type = .{ .known = .Q4_0 },
        .raw_bytes = up_q4,
        .shape = &up_shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    const down_values = try allocator.alloc(f32, hidden * intermediate);
    defer allocator.free(down_values);
    @memset(down_values, 0);
    for (0..hidden) |index| {
        down_values[index * intermediate + index] = 1;
        down_values[index * intermediate + hidden + index] = 0.25;
    }
    const down_q4 = try quant_codec.quantizeQ4_0FromF32(allocator, down_values);
    defer allocator.free(down_q4);
    const down_shape = [_]i64{ hidden, intermediate };
    const down_storage = QuantizedStorage{
        .tensor_type = .{ .known = .Q4_0 },
        .raw_bytes = down_q4,
        .shape = &down_shape,
        .raw_owned = false,
        .allocator = allocator,
    };

    const hidden_bias_values = try allocator.alloc(f32, hidden);
    defer allocator.free(hidden_bias_values);
    @memset(hidden_bias_values, 0);
    var hidden_bias = try MetalTensor.ownedCloneFrom(hidden_bias_values, &[_]i32{@intCast(hidden)});
    defer hidden_bias.deinit();
    const intermediate_bias_values = try allocator.alloc(f32, intermediate);
    defer allocator.free(intermediate_bias_values);
    @memset(intermediate_bias_values, 0);
    var intermediate_bias = try MetalTensor.ownedCloneFrom(intermediate_bias_values, &[_]i32{@intCast(intermediate)});
    defer intermediate_bias.deinit();

    var prep_stats: ops.NativeQuantTimingStats = .{};
    for (0..4) |slot| {
        try Compare.prepareLinear(&provider, slot, &identity_storage, hidden_bias, hidden, hidden, &prep_stats);
    }
    try Compare.prepareLinear(&provider, 4, &up_storage, intermediate_bias, hidden, intermediate, &prep_stats);
    try Compare.prepareLinear(&provider, 5, &down_storage, hidden_bias, intermediate, hidden, &prep_stats);

    const norm_weight_values = try allocator.alloc(f32, hidden);
    defer allocator.free(norm_weight_values);
    const norm_bias_values = try allocator.alloc(f32, hidden);
    defer allocator.free(norm_bias_values);
    for (norm_weight_values, norm_bias_values, 0..) |*weight, *bias, index| {
        weight.* = 0.75 + @as(f32, @floatFromInt(index % 7)) * 0.03125;
        bias.* = @as(f32, @floatFromInt(@as(i32, @intCast(index % 5)) - 2)) * 0.01;
    }
    var norm_weight = try MetalTensor.ownedCloneFrom(norm_weight_values, &[_]i32{@intCast(hidden)});
    defer norm_weight.deinit();
    var norm_bias = try MetalTensor.ownedCloneFrom(norm_bias_values, &[_]i32{@intCast(hidden)});
    defer norm_bias.deinit();
    for (0..2) |slot| {
        try std.testing.expect(try decoderRuntimePrepareLayerNorm(&provider, .{
            .slot = slot,
            .weight = norm_weight,
            .bias = norm_bias,
            .hidden_size = hidden,
        }));
    }

    const input_values = try allocator.alloc(f32, rows * hidden);
    defer allocator.free(input_values);
    const residual_values = try allocator.alloc(f32, rows * hidden);
    defer allocator.free(residual_values);
    for (input_values, residual_values, 0..) |*input_value, *residual_value, index| {
        input_value.* = @as(f32, @floatFromInt(@as(i32, @intCast(index % 23)) - 11)) * 0.0625;
        residual_value.* = @as(f32, @floatFromInt(@as(i32, @intCast(index % 13)) - 6)) * 0.03125;
    }
    const input_shape = [_]i32{ @intCast(rows), @intCast(hidden) };
    var input = try testDeviceTensorFromSlice(runtime, input_values, &input_shape);
    defer input.deinit();
    var residual = try testDeviceTensorFromSlice(runtime, residual_values, &input_shape);
    defer residual.deinit();

    // GLiNER2 can fall from a compiled planned region into an f16 MPS-backed
    // linear while the coalesced encoder is still open. MPS creates its own
    // encoder, so this transition must close the planned encoder instead of
    // letting the driver abort the process.
    try beginFrame(runtime);
    errdefer if (hasActiveFrame(runtime)) cancelFrame(runtime) catch {};
    try beginPlannedComputeScope(runtime, @intFromEnum(ComputeSource.dense_linear), .ffn);
    var planned_mps_linear = (try tryApplyDenseRuntimeLinear(&provider, 0, input, rows, hidden, hidden)) orelse
        return error.UnexpectedNull;
    defer planned_mps_linear.deinit();
    try endPlannedComputeScope(runtime);
    try submitFrame(runtime);
    try waitFrame(runtime);

    try beginFrame(runtime);
    errdefer if (hasActiveFrame(runtime)) cancelFrame(runtime) catch {};
    // GLiNER's fused DeBERTa layer opens a planned layer encoder before QKV.
    // Packed F16 MPS QKV must close that encoder for the transition rather than
    // decline the operation and force the entire layer onto the fallback path.
    try beginPlannedComputeScope(runtime, @intFromEnum(ComputeSource.layer), .layer);
    var packed_qkv = (try tryApplyDenseRuntimeLinearQkv(&provider, 0, 1, 2, input, rows, hidden, hidden, hidden)) orelse
        return error.UnexpectedNull;
    defer packed_qkv.first.deinit();
    defer packed_qkv.second.deinit();
    defer packed_qkv.third.deinit();
    try endPlannedComputeScope(runtime);
    try submitFrame(runtime);
    try waitFrame(runtime);
    const packed_stats = runtimeMemorySnapshot(runtime);
    try std.testing.expectEqual(@as(u64, 1), packed_stats.dense_qkv_packed_calls);
    try std.testing.expectEqual(@as(u64, 0), packed_stats.dense_qkv_packed_fallbacks);
    try std.testing.expectEqual(
        @as(u64, 3 * hidden * hidden * @sizeOf(u16) + 3 * hidden * @sizeOf(f32)),
        packed_stats.dense_qkv_packed_bytes,
    );

    var q_reference = (try tryApplyDenseRuntimeLinear(&provider, 0, input, rows, hidden, hidden)) orelse return error.UnexpectedNull;
    defer q_reference.deinit();
    try Compare.close("planned-mps-linear", try tensorHostSlice(&q_reference), try tensorHostSlice(&planned_mps_linear));
    var k_reference = (try tryApplyDenseRuntimeLinear(&provider, 1, input, rows, hidden, hidden)) orelse return error.UnexpectedNull;
    defer k_reference.deinit();
    var v_reference = (try tryApplyDenseRuntimeLinear(&provider, 2, input, rows, hidden, hidden)) orelse return error.UnexpectedNull;
    defer v_reference.deinit();
    try Compare.close("packed-q", try tensorHostSlice(&q_reference), try tensorHostSlice(&packed_qkv.first));
    try Compare.close("packed-k", try tensorHostSlice(&k_reference), try tensorHostSlice(&packed_qkv.second));
    try Compare.close("packed-v", try tensorHostSlice(&v_reference), try tensorHostSlice(&packed_qkv.third));

    var activation_stats: ops.NativeQuantTimingStats = .{};
    var fused_attention = (try tryApplyDenseRuntimeLinearLayerNorm(&provider, 3, 0, input, residual, rows, hidden, hidden, 1e-5)) orelse
        return error.UnexpectedNull;
    defer fused_attention.deinit();
    var attention_projected = (try tryApplyDenseRuntimeLinear(&provider, 3, input, rows, hidden, hidden)) orelse return error.UnexpectedNull;
    defer attention_projected.deinit();
    var attention_added = (try decoderRuntimeApplyAdd(&provider, .{
        .lhs = attention_projected,
        .rhs = residual,
        .dim = hidden,
    }, &activation_stats)) orelse return error.UnexpectedNull;
    defer attention_added.deinit();
    var attention_reference = (try decoderRuntimeApplyLayerNorm(&provider, .{
        .input = attention_added,
        .slot = 0,
        .hidden_size = hidden,
        .eps = 1e-5,
    }, &activation_stats)) orelse return error.UnexpectedNull;
    defer attention_reference.deinit();
    try Compare.close("attention-linear-layer-norm", try tensorHostSlice(&attention_reference), try tensorHostSlice(&fused_attention));

    var fused_ffn = (try tryApplyDenseRuntimeFfnLayerNorm(
        &provider,
        4,
        5,
        1,
        input,
        residual,
        rows,
        hidden,
        intermediate,
        1e-5,
        .gelu,
    )) orelse return error.UnexpectedNull;
    defer fused_ffn.deinit();
    var first = (try tryApplyDenseRuntimeLinear(&provider, 4, input, rows, hidden, intermediate)) orelse return error.UnexpectedNull;
    defer first.deinit();
    var activated = (try decoderRuntimeApplyActivation(&provider, .{
        .kind = @as(ops.DecoderRuntimeActivationKind, .gelu),
        .input = first,
        .dim = intermediate,
    }, &activation_stats)) orelse return error.UnexpectedNull;
    defer activated.deinit();
    var second = (try tryApplyDenseRuntimeLinear(&provider, 5, activated, rows, intermediate, hidden)) orelse return error.UnexpectedNull;
    defer second.deinit();
    var ffn_added = (try decoderRuntimeApplyAdd(&provider, .{
        .lhs = second,
        .rhs = residual,
        .dim = hidden,
    }, &activation_stats)) orelse return error.UnexpectedNull;
    defer ffn_added.deinit();
    var ffn_reference = (try decoderRuntimeApplyLayerNorm(&provider, .{
        .input = ffn_added,
        .slot = 1,
        .hidden_size = hidden,
        .eps = 1e-5,
    }, &activation_stats)) orelse return error.UnexpectedNull;
    defer ffn_reference.deinit();
    try Compare.close("ffn-layer-norm", try tensorHostSlice(&ffn_reference), try tensorHostSlice(&fused_ffn));
}

test "metal native decoder runtime bf16 multi-row linear matches identity projection" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;

    const allocator = std.testing.allocator;
    const rows: usize = 3;
    const hidden_size: usize = 128;
    const out_dim: usize = 128;
    const bf16_one: u16 = 0x3f80;

    var bf16_weight_words = try allocator.alloc(u16, hidden_size * out_dim);
    defer allocator.free(bf16_weight_words);
    @memset(bf16_weight_words, 0);
    for (0..out_dim) |out| {
        bf16_weight_words[out * hidden_size + out] = bf16_one;
    }
    const bf16_weight_bytes = std.mem.sliceAsBytes(bf16_weight_words);

    const bias_data = try allocator.alloc(f32, out_dim);
    defer allocator.free(bias_data);
    @memset(bias_data, 0.0);
    var linear_bias = try MetalTensor.ownedCloneFrom(bias_data, &[_]i32{@intCast(out_dim)});
    defer linear_bias.deinit();

    var dummy_weight_value = [_]f32{0.0};
    const dummy_weight = MetalTensor.borrowed(dummy_weight_value[0..].ptr, 1, &[_]i32{0});
    var prep_stats: ops.NativeQuantTimingStats = .{};
    try std.testing.expect(try decoderRuntimePrepareLinear(&provider, .{
        .slot = 0,
        .weight = dummy_weight,
        .bias = linear_bias,
        .quantized_storage = null,
        .in_dim = hidden_size,
        .out_dim = out_dim,
        .retain_dense_fallback = false,
        .dense_bf16_bytes = bf16_weight_bytes,
        .dense_bf16_no_copy_safe = true,
    }, &prep_stats));

    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;
    const input_data = try allocator.alloc(f32, rows * hidden_size);
    defer allocator.free(input_data);
    for (input_data, 0..) |*value, index| {
        const row = index / hidden_size;
        const col = index % hidden_size;
        value.* = @as(f32, @floatFromInt(row * 1000 + col));
    }
    var input = try testDeviceTensorFromSlice(runtime, input_data, &[_]i32{ @intCast(rows), @intCast(hidden_size) });
    defer input.deinit();

    var output = (try decoderRuntimeApplyLinear(&provider, .{
        .slot = 0,
        .input = input,
        .in_dim = hidden_size,
        .out_dim = out_dim,
    })) orelse return error.UnexpectedNull;
    defer output.deinit();

    var output_mut = output;
    const actual = try tensorHostSlice(&output_mut);
    try std.testing.expectEqual(rows * out_dim, actual.len);
    for (0..rows) |row| {
        for (0..out_dim) |col| {
            try std.testing.expectApproxEqAbs(input_data[row * hidden_size + col], actual[row * out_dim + col], 1e-3);
        }
    }
}

test "metal native decoder runtime f16 MPS linear transitions from planned encoder" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    const runtime = provider.raw_decode_runtime orelse return error.SkipZigTest;

    const allocator = std.testing.allocator;
    const rows: usize = 3;
    const hidden_size: usize = 128;
    const slot: usize = 0;

    const f16_one: u16 = @bitCast(@as(f16, 1.0));
    const f16_weights = try allocator.alloc(u16, hidden_size * hidden_size);
    defer allocator.free(f16_weights);
    @memset(f16_weights, 0);
    for (0..hidden_size) |i| f16_weights[i * hidden_size + i] = f16_one;
    const f16_weight_bytes = std.mem.sliceAsBytes(f16_weights);

    const bias = try allocator.alloc(f32, hidden_size);
    defer allocator.free(bias);
    @memset(bias, 0);
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_prepare_linear_f16(
        runtime,
        slot,
        f16_weight_bytes.ptr,
        f16_weight_bytes.len,
        bias.ptr,
        hidden_size,
        hidden_size,
    ));

    const input_data = try allocator.alloc(f32, rows * hidden_size);
    defer allocator.free(input_data);
    for (input_data, 0..) |*value, i| {
        const centered: i32 = @intCast(i % 29);
        value.* = @as(f32, @floatFromInt(centered - 14)) * 0.125;
    }
    const shape = [_]i32{ @intCast(rows), @intCast(hidden_size) };
    var input = try testDeviceTensorFromSlice(runtime, input_data, &shape);
    defer input.deinit();
    var scratch = try MetalTensor.deviceAllocate(runtime, input_data.len * @sizeOf(f32), .private, &shape);
    defer scratch.deinit();
    var output = try MetalTensor.deviceAllocate(runtime, input_data.len * @sizeOf(f32), .private, &shape);
    defer output.deinit();

    try beginFrame(runtime);
    errdefer cancelFrame(runtime) catch {};
    try beginPlannedComputeScope(runtime, @intFromEnum(ComputeSource.dense_linear), .ffn);
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_apply_add_device(
        runtime,
        input.deviceHandle(),
        input.deviceByteOffset(),
        input.deviceHandle(),
        input.deviceByteOffset(),
        input_data.len,
        scratch.deviceHandle(),
        scratch.deviceByteOffset(),
    ));
    try std.testing.expectEqual(@as(c_int, 0), termite_metal_decode_runtime_apply_linear_multi_row_device(
        runtime,
        slot,
        input.deviceHandle(),
        input.deviceByteOffset(),
        rows,
        hidden_size,
        hidden_size,
        output.deviceHandle(),
        output.deviceByteOffset(),
    ));
    try endPlannedComputeScope(runtime);
    try submitFrame(runtime);
    try waitFrame(runtime);

    const actual = try output.toHostSlice();
    try std.testing.expectEqual(input_data.len, actual.len);
    for (input_data, actual) |expected, got| {
        try std.testing.expectApproxEqAbs(expected, got, 2e-3);
    }
}

test "metal native decoder runtime activation scratch pool and hidden state" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const metal_native_provider = @import("metal_native_provider.zig");
    var provider = try metal_native_provider.MetalNativeProvider.create();
    defer provider.deinitOwned();
    if (!provider.hasDecoderRuntime()) return error.SkipZigTest;
    const runtime = provider.raw_decode_runtime;

    // Hidden-state ping-pong: front/back must be distinct live buffers, and
    // capacity/max_rows accessors must report what we reserved.
    const hidden_size: usize = 128;
    const max_prefill_rows: usize = 8;
    try reserveHiddenState(runtime, max_prefill_rows, hidden_size);
    try std.testing.expectEqual(max_prefill_rows, hiddenStateMaxRows(runtime));
    try std.testing.expectEqual(max_prefill_rows * hidden_size * @sizeOf(f32), hiddenStateCapacity(runtime));

    const front = hiddenStateBuffer(runtime, .front) orelse return error.UnexpectedNull;
    defer termite_metal_buffer_release(front);
    const back = hiddenStateBuffer(runtime, .back) orelse return error.UnexpectedNull;
    defer termite_metal_buffer_release(back);
    try std.testing.expect(front != back);

    const hidden_seed = try std.testing.allocator.alloc(f32, hidden_size * 2);
    defer std.testing.allocator.free(hidden_seed);
    for (hidden_seed, 0..) |*value, i| value.* = @floatFromInt(i);
    const hidden_shape = [_]i32{ 2, @intCast(hidden_size) };
    var seed_tensor = try testDeviceTensorFromSlice(runtime.?, hidden_seed, &hidden_shape);
    defer seed_tensor.deinit();
    try std.testing.expectEqual(
        @as(c_int, 0),
        termite_metal_buffer_copy(
            runtime,
            seed_tensor.deviceHandle(),
            seed_tensor.deviceByteOffset(),
            front,
            0,
            seed_tensor.deviceByteLen(),
        ),
    );
    const hidden_seed_copy = try std.testing.allocator.alloc(f32, hidden_seed.len);
    defer std.testing.allocator.free(hidden_seed_copy);
    try std.testing.expectEqual(
        @as(c_int, 0),
        termite_metal_buffer_download(
            runtime,
            front,
            0,
            @ptrCast(hidden_seed_copy.ptr),
            seed_tensor.deviceByteLen(),
        ),
    );
    try std.testing.expectEqualSlices(f32, hidden_seed, hidden_seed_copy);

    // Growing the reservation must keep max_rows current and not shrink capacity.
    const prev_capacity = hiddenStateCapacity(runtime);
    try reserveHiddenState(runtime, max_prefill_rows * 2, hidden_size);
    try std.testing.expectEqual(max_prefill_rows * 2, hiddenStateMaxRows(runtime));
    try std.testing.expect(hiddenStateCapacity(runtime) >= prev_capacity);

    // Scratch pool acquisition returns distinct handles until exhausted.
    const capacity = 16; // TERMITE_METAL_SCRATCH_POOL_CAPACITY
    var handles: [capacity]?*anyopaque = [_]?*anyopaque{null} ** capacity;
    var acquired: usize = 0;
    errdefer for (handles[0..acquired]) |h| {
        if (h) |ptr| releaseScratch(runtime, ptr);
    };
    for (0..capacity) |i| {
        handles[i] = try acquireScratch(runtime, 4096);
        acquired += 1;
        for (0..i) |j| {
            try std.testing.expect(handles[i] != handles[j]);
        }
    }
    try std.testing.expectError(ScratchAcquireError.ScratchPoolExhausted, acquireScratch(runtime, 4096));

    // Release then re-acquire reuses a previously-returned slot. The pool
    // scans linearly for the first idle slot with enough capacity, so
    // releasing slot 3 and re-acquiring must return the same buffer handle —
    // `__bridge_retained` yields the same pointer value for the same
    // underlying MTLBuffer across acquires.
    const released_handle: *anyopaque = handles[3].?;
    releaseScratch(runtime, released_handle);
    handles[3] = null;
    const reused = try acquireScratch(runtime, 4096);
    try std.testing.expectEqual(released_handle, reused);
    handles[3] = reused;
    releaseScratch(runtime, handles[3].?);
    handles[3] = null;

    // reset_state marks every scratch slot idle, so we can re-acquire the full pool.
    _ = termite_metal_decode_runtime_reset_state(runtime);
    for (handles[0..capacity]) |h| {
        if (h) |ptr| releaseScratch(runtime, ptr);
    }
    handles = [_]?*anyopaque{null} ** capacity;
    acquired = 0;

    // Inside an active/submitted frame, release retires the slot until the
    // frame is waited. Re-acquire must not hand out the same buffer while
    // queued GPU work may still reference it.
    const frame_scratch = try acquireScratch(runtime, 4096);
    try beginFrame(runtime);
    releaseScratch(runtime, frame_scratch);
    const during_frame_scratch = try acquireScratch(runtime, 4096);
    try std.testing.expect(during_frame_scratch != frame_scratch);
    try submitFrame(runtime);
    releaseScratch(runtime, during_frame_scratch);
    try waitFrame(runtime);
    const after_frame_scratch = try acquireScratch(runtime, 4096);
    try std.testing.expectEqual(frame_scratch, after_frame_scratch);
    releaseScratch(runtime, after_frame_scratch);

    for (0..capacity) |i| {
        handles[i] = try acquireScratch(runtime, 4096);
        acquired += 1;
    }
    for (handles[0..capacity]) |h| {
        if (h) |ptr| releaseScratch(runtime, ptr);
    }
}

test "metal donated KV on-frame attention executes on caller frame" {
    if (!build_options.enable_metal) return error.SkipZigTest;
    if (!metalDeviceAvailable()) return error.SkipZigTest;

    const kv_runtime = termite_metal_decode_runtime_create() orelse return error.SkipZigTest;
    defer termite_metal_decode_runtime_destroy(kv_runtime);
    defer _ = termite_metal_decode_runtime_reset_state(kv_runtime);
    const frame_runtime = termite_metal_decode_runtime_create() orelse return error.SkipZigTest;
    defer termite_metal_decode_runtime_destroy(frame_runtime);
    defer _ = termite_metal_decode_runtime_reset_state(frame_runtime);
    if (termite_metal_decode_runtime_ready(kv_runtime) == 0 or
        termite_metal_decode_runtime_ready(frame_runtime) == 0)
    {
        return error.SkipZigTest;
    }

    var q = try testDeviceTensorFromSlice(frame_runtime, &[_]f32{1.0}, &[_]i32{ 1, 1 });
    defer q.deinit();
    var k = try testDeviceTensorFromSlice(kv_runtime, &[_]f32{2.0}, &[_]i32{ 1, 1 });
    defer k.deinit();
    var v = try testDeviceTensorFromSlice(kv_runtime, &[_]f32{7.0}, &[_]i32{ 1, 1 });
    defer v.deinit();
    var output = try MetalTensor.deviceAllocate(frame_runtime, @sizeOf(f32), .private, &[_]i32{ 1, 1 });
    defer output.deinit();

